#!/usr/bin/env python3
"""
Global Fuel Price Trends & Policy Impact Analysis Report Generator
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib
matplotlib.use('Agg')
matplotlib.rcParams['font.family'] = 'DejaVu Sans'
from io import StringIO, BytesIO
import base64
from pathlib import Path
from datetime import datetime
import json

# Load data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])

print(f"Data shape: {df.shape}")
print(f"Date range: {df['date'].min()} to {df['date'].max()}")
print(f"Countries: {df['country'].nunique()}")
print(f"Regions: {df['region'].unique()}")

# ============================================================================
# COMPUTE KPIs AND ANALYSIS
# ============================================================================

print("\nComputing KPIs...")

# 1. Global Overview Statistics
avg_petrol = df['petrol_usd_liter'].mean()
avg_diesel = df['diesel_usd_liter'].mean()
avg_lpg = df['lpg_usd_liter'].mean()
avg_brent = df['brent_crude_usd'].mean()

petrol_range = (df['petrol_usd_liter'].min(), df['petrol_usd_liter'].max())
diesel_range = (df['diesel_usd_liter'].min(), df['diesel_usd_liter'].max())

# 2. Brent-to-Retail Correlation
brent_petrol_corr = df['brent_crude_usd'].corr(df['petrol_usd_liter'])
brent_diesel_corr = df['brent_crude_usd'].corr(df['diesel_usd_liter'])

# 3. Subsidy Price Dampening Effect
high_subsidy_petrol = df[df['subsidy_level'] == 'High']['petrol_usd_liter'].mean()
low_subsidy_petrol = df[df['subsidy_level'] == 'Low']['petrol_usd_liter'].mean()
subsidy_effect = ((low_subsidy_petrol - high_subsidy_petrol) / high_subsidy_petrol) * 100

# 4. Regional Price Spread (yearly)
df['year'] = df['date'].dt.year
regional_yearly = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().unstack()

# 5. Tax by Income Level
tax_by_income = df.groupby('income_level')['tax_percentage'].mean()

# 6. Time series data for Brent and retail
weekly_data = df.groupby('date').agg({
    'petrol_usd_liter': 'mean',
    'diesel_usd_liter': 'mean',
    'lpg_usd_liter': 'mean',
    'brent_crude_usd': 'first'
}).reset_index()

# 7. Volatility analysis - yearly
yearly_volatility = df.groupby('year')['petrol_usd_liter'].std()

# 8. Subsidy analysis by income level
subsidy_by_income = df.groupby(['income_level', 'subsidy_level'])['petrol_usd_liter'].mean().unstack()

# 9. Regional averages
regional_avg = df.groupby('region')['petrol_usd_liter'].agg(['mean', 'std', 'min', 'max'])

# 10. Price by year and fuel type
yearly_prices = df.groupby('year')[['petrol_usd_liter', 'diesel_usd_liter', 'lpg_usd_liter', 'brent_crude_usd']].mean()

# 11. High volatility periods
df['price_volatility'] = df.groupby('date')['petrol_usd_liter'].transform('std')
# Weekly volatility of brent
brent_weekly_change = df.groupby('date')['brent_crude_usd'].first().pct_change() * 100
high_vol_weeks = brent_weekly_change[abs(brent_weekly_change) > brent_weekly_change.quantile(0.95)]

# 12. Countries with highest/lowest prices
country_avg = df.groupby('country')['petrol_usd_liter'].mean()
top5_countries = country_avg.nlargest(5)
bottom5_countries = country_avg.nsmallest(5)

# ============================================================================
# CREATE VISUALIZATIONS
# ============================================================================

print("\nCreating visualizations...")

# Color palette
COLORS = {
    'primary': '#1e40af',
    'secondary': '#6b7280',
    'accent': '#059669',
    'warning': '#d97706',
    'danger': '#dc2626',
    'bg_light': '#f8fafc'
}

def save_svg_to_base64(fig):
    """Convert matplotlib figure to base64 encoded SVG"""
    buf = BytesIO()
    fig.savefig(buf, format='svg', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

def create_figure(width=8, height=4):
    fig, ax = plt.subplots(figsize=(width, height))
    return fig, ax

# Chart 1: Brent Crude vs Retail Prices Over Time
print("  Creating Brent vs Retail chart...")
fig, ax = plt.subplots(figsize=(12, 5))
ax.plot(weekly_data['date'], weekly_data['brent_crude_usd']/10, label='Brent Crude (/10, USD/bbl)', color='#dc2626', linewidth=1.5)
ax.plot(weekly_data['date'], weekly_data['petrol_usd_liter'], label='Petrol (USD/L)', color='#1e40af', linewidth=1.5)
ax.plot(weekly_data['date'], weekly_data['diesel_usd_liter'], label='Diesel (USD/L)', color='#059669', linewidth=1.5)
ax.set_xlabel('Date')
ax.set_ylabel('Price (USD)')
ax.set_title('Brent Crude vs Retail Fuel Prices (2020-2026)', fontweight='bold')
ax.legend(loc='upper left')
ax.grid(True, alpha=0.3)
plt.tight_layout()
brent_vs_retail_svg = save_svg_to_base64(fig)
plt.close()

# Chart 2: Regional Price Comparison (bar chart)
print("  Creating regional comparison chart...")
regional_order = regional_avg.sort_values('mean', ascending=False).index.tolist()
fig, ax = plt.subplots(figsize=(10, 5))
colors_bar = [COLORS['primary'], COLORS['secondary'], COLORS['accent'], COLORS['warning'], '#8b5cf6', '#ec4899', '#14b8a6']
bars = ax.bar(range(len(regional_order)), [regional_avg.loc[r, 'mean'] for r in regional_order], color=colors_bar)
ax.set_xticks(range(len(regional_order)))
ax.set_xticklabels(regional_order, rotation=45, ha='right')
ax.set_ylabel('Average Petrol Price (USD/L)')
ax.set_title('Average Retail Petrol Price by Region', fontweight='bold')
ax.grid(True, alpha=0.3, axis='y')
for i, (bar, val) in enumerate(zip(bars, [regional_avg.loc[r, 'mean'] for r in regional_order])):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.02, f'${val:.2f}', ha='center', fontsize=9)
plt.tight_layout()
regional_bar_svg = save_svg_to_base64(fig)
plt.close()

# Chart 3: Regional Price Trends Over Years
print("  Creating regional trends chart...")
fig, ax = plt.subplots(figsize=(12, 5))
regions_to_plot = ['Middle East', 'Europe', 'North America', 'Asia', 'Africa', 'South America', 'Oceania']
colors_trend = ['#1e40af', '#059669', '#dc2626', '#d97706', '#8b5cf6', '#ec4899', '#14b8a6']
