        'Min': round(r['min'], 3),
        'Max': round(r['max'], 3)
    })

# Yearly summary
yearly_summary = []
for year in sorted(df['year'].unique()):
    year_data = df[df['year'] == year]
    yearly_summary.append({
        'Year': year,
        'Avg Petrol': round(year_data['petrol_usd_liter'].mean(), 3),
        'Avg Diesel': round(year_data['diesel_usd_liter'].mean(), 3),
        'Avg LPG': round(year_data['lpg_usd_liter'].mean(), 3),
        'Avg Brent': round(year_data['brent_crude_usd'].mean(), 1),
        'Volatility (Petrol Std)': round(year_data['petrol_usd_liter'].std(), 3)
    })

