            list-style: none;
        }}
        .findings-list li {{
            padding: 12px 15px;
            margin: 10px 0;
            background: var(--bg-light);
            border-radius: 8px;
            border-left: 4px solid var(--primary);
        }}
        .findings-list li strong {{ color: var(--primary); }}
        .two-col {{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }}
        @media (max-width: 768px) {{
            .two-col {{ grid-template-columns: 1fr; }}
        }}
        .footer {{
            text-align: center;
            padding: 30px;
            color: var(--secondary);
            font-size: 0.85rem;
            border-top: 1px solid var(--border);
            margin-top: 40px;
        }}
        .toc {{
            background: var(--bg-light);
            padding: 20px;
            border-radius: 8px;
            margin: 20px 0;
        }}
        .toc h3 {{ margin-top: 0; }}
        .toc ol {{ margin-left: 20px; }}
        .toc li {{ margin: 5px 0; }}
        .toc a {{ color: var(--primary); text-decoration: none; }}
        .toc a:hover {{ text-decoration: underline; }}
    </style>
</head>
<body>
    <div class="header">
        <h1>Global Fuel Price Trends & Policy Impact Analysis</h1>
        <div class="subtitle">Comprehensive Analysis of Retail Fuel Prices Across 84 Countries (2020–2026)</div>
        <div class="meta">Report Generated: {datetime.now().strftime('%B %d, %Y')} | Data Source: Global Energy Ministries, EIA, OPEC, World Bank</div>
    </div>

    <div class="container">
        <!-- TABLE OF CONTENTS -->
        <div class="toc">
            <h3>Report Contents</h3>
            <ol>
                <li><a href="#global-overview">Global Fuel Price Overview</a></li>
                <li><a href="#temporal-trends">Temporal Price Trends & Volatility</a></li>
                <li><a href="#regional-comparison">Regional Price Disparities</a></li>
                <li><a href="#subsidy-tax">Impact of Subsidies and Taxation</a></li>
                <li><a href="#income-segmentation">Fuel Affordability by Income Level</a></li>
                <li><a href="#key-findings">Key Findings & Policy Implications</a></li>
            </ol>
        </div>

        <!-- SECTION 1: GLOBAL OVERVIEW -->
        <div class="section" id="global-overview">
            <h2>1. Global Fuel Price Overview</h2>

            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="kpi-value">${avg_petrol:.3f}</div>
                    <div class="kpi-label">Avg Petrol Price (USD/L)</div>
                </div>
                <div class="kpi-card success">
                    <div class="kpi-value">${avg_diesel:.3f}</div>
                    <div class="kpi-label">Avg Diesel Price (USD/L)</div>
                </div>
                <div class="kpi-card warning">
                    <div class="kpi-value">${avg_lpg:.3f}</div>
                    <div class="kpi-label">Avg LPG Price (USD/L)</div>
                </div>
                <div class="kpi-card danger">
                    <div class="kpi-value">${avg_brent:.1f}</div>
                    <div class="kpi-label">Avg Brent Crude (USD/bbl)</div>
                </div>
            </div>

            <div class="highlight-box">
                <strong>Dataset Summary:</strong> This analysis covers {df['country'].nunique()} countries across {df['region'].nunique()} regions,
                spanning from {df['date'].min().strftime('%B %Y')} to {df['date'].max().strftime('%B %Y')}.
                The dataset contains {len(df):,} weekly observations.
            </div>

            <h3>Price Ranges (2020-2026)</h3>
            <table>
                <tr><th>Fuel Type</th><th>Minimum (USD/L)</th><th>Maximum (USD/L)</th><th>Range</th></tr>
                <tr><td>Petrol</td><td>${petrol_range[0]:.3f}</td><td>${petrol_range[1]:.3f}</td><td>${petrol_range[1] - petrol_range[0]:.3f}</td></tr>
                <tr><td>Diesel</td><td>${diesel_range[0]:.3f}</td><td>${diesel_range[1]:.3f}</td><td>${diesel_range[1] - diesel_range[0]:.3f}</td></tr>
            </table>

            <h3>Countries with Highest/Lowest Petrol Prices</h3>
            <div class="two-col">
                <div>
                    <h4>Top 5 Most Expensive</h4>
                    <table>
                        <tr><th>Country</th><th>Region</th><th>Price (USD/L)</th></tr>
                        {''.join(f"<tr><td>{c['Country']}</td><td>{c['Region']}</td><td>${c['Avg Petrol Price (USD/L)']:.3f}</td></tr>" for c in top_countries_data)}
                    </table>
                </div>
                <div>
                    <h4>Top 5 Most Affordable</h4>
                    <table>
                        <tr><th>Country</th><th>Region</th><th>Price (USD/L)</th></tr>
                        {''.join(f"<tr><td>{c['Country']}</td><td>{c['Region']}</td><td>${c['Avg Petrol Price (USD/L)']:.3f}</td></tr>" for c in bottom_countries_data)}
                    </table>
                </div>
            </div>
        </div>

        <!-- SECTION 2: TEMPORAL TRENDS -->
        <div class="section" id="temporal-trends">
            <h2>2. Temporal Price Trends & Volatility</h2>

            <div class="kpi-grid">
                <div class="kpi-card success">
                    <div class="kpi-value">{brent_petrol_corr:.3f}</div>
                    <div class="kpi-label">Brent-Petrol Correlation</div>
                </div>
                <div class="kpi-card success">
                    <div class="kpi-value">{brent_diesel_corr:.3f}</div>
                    <div class="kpi-label">Brent-Diesel Correlation</div>
                </div>
            </div>

            <div class="callout info">
                <strong>Key Insight:</strong> The strong positive correlation ({brent_petrol_corr:.2f}) between Brent Crude and retail petrol prices
                confirms that international oil benchmarks are the primary driver of retail fuel costs globally.
            </div>

            <h3>Brent Crude vs Retail Prices Over Time</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{brent_vs_retail_svg}" alt="Brent Crude vs Retail Prices">
                <div class="chart-caption">Figure 1: Weekly Brent Crude benchmark compared to average retail petrol and diesel prices</div>
            </div>

            <h3>Monthly Price Volatility with Major Events</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{volatility_svg}" alt="Price Volatility Analysis">
                <div class="chart-caption">Figure 2: Monthly average petrol price showing COVID-19 demand shock (yellow) and 2022 energy crisis (red)</div>
            </div>

            <h3>Yearly Average Fuel Prices</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{yearly_trends_svg}" alt="Yearly Fuel Price Trends">
                <div class="chart-caption">Figure 3: Annual average prices for petrol, diesel, and LPG</div>
            </div>

            <table>
                <tr><th>Year</th><th>Avg Petrol</th><th>Avg Diesel</th><th>Avg LPG</th><th>Avg Brent</th><th>Volatility (Std)</th></tr>
                {''.join(f"<tr><td>{y['Year']}</td><td>${y['Avg Petrol']:.3f}</td><td>${y['Avg Diesel']:.3f}</td><td>${y['Avg LPG']:.3f}</td><td>${y['Avg Brent']:.1f}</td><td>{y['Volatility (Petrol Std)']:.3f}</td></tr>" for y in yearly_summary)}
            </table>

            <div class="callout warning">
                <strong>Volatility Events:</strong> The data reveals two major volatility periods:
                <ul style="margin-top: 10px; margin-left: 20px;">
                    <li><strong>COVID-19 Shock (Q1-Q2 2020):</strong> Brent crude collapsed from ~$70 to ~$30/bbl as global demand plummeted</li>
                    <li><strong>2022 Energy Crisis:</strong> Brent surged to ~$120/bbl following geopolitical tensions, driving retail prices to decade highs</li>
                </ul>
            </div>
        </div>

        <!-- SECTION 3: REGIONAL COMPARISON -->
        <div class="section" id="regional-comparison">
            <h2>3. Regional Price Disparities</h2>

            <h3>Regional Average Petrol Prices</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{regional_bar_svg}" alt="Regional Price Comparison">
                <div class="chart-caption">Figure 4: Average retail petrol price by region (2020-2026)</div>
            </div>

            <h3>Regional Price Trends Over Time</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{regional_trends_svg}" alt="Regional Trends">
                <div class="chart-caption">Figure 5: Evolution of regional petrol prices from 2020 to 2026</div>
            </div>

            <h3>Regional Price Distribution</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{distribution_svg}" alt="Price Distribution">
                <div class="chart-caption">Figure 6: Regional petrol price distribution showing mean, standard deviation, min, and max</div>
            </div>

            <table>
                <tr><th>Region</th><th>Average Price (USD/L)</th><th>Std Deviation</th><th>Minimum</th><th>Maximum</th></tr>
                {''.join(f"<tr><td>{r['Region']}</td><td>${r['Avg Price (USD/L)']:.3f}</td><td>{r['Std Dev']:.3f}</td><td>${r['Min']:.3f}</td><td>${r['Max']:.3f}</td></tr>" for r in regional_summary)}
            </table>

            <div class="callout info">
                <strong>Regional Spread:</strong> The gap between the highest-priced region (Middle East) and lowest-priced region (Africa)
                reflects a combination of subsidy policies, taxation levels, and local market conditions.
            </div>
        </div>

        <!-- SECTION 4: SUBSIDY & TAX ANALYSIS -->
        <div class="section" id="subsidy-tax">
            <h2>4. Impact of Subsidies and Taxation on Retail Prices</h2>

            <div class="kpi-grid">
                <div class="kpi-card warning">
                    <div class="kpi-value">{subsidy_effect:.1f}%</div>
                    <div class="kpi-label">Subsidy Price Dampening Effect</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">${high_subsidy_petrol:.3f}</div>
                    <div class="kpi-label">High Subsidy Avg (USD/L)</div>
                </div>
                <div class="kpi-card danger">
                    <div class="kpi-value">${low_subsidy_petrol:.3f}</div>
                    <div class="kpi-label">Low Subsidy Avg (USD/L)</div>
                </div>
            </div>

            <div class="callout success">
                <strong>Subsidy Effectiveness:</strong> High-subsidy countries maintain petrol prices that are {subsidy_effect:.1f}% lower
                on average than low-subsidy countries, demonstrating the significant price-dampening effect of fuel subsidies.
            </div>

            <h3>Subsidy Impact by Income Level</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{subsidy_impact_svg}" alt="Subsidy Impact by Income">
                <div class="chart-caption">Figure 7: Comparison of petrol prices between high-subsidy and low-subsidy countries, segmented by income level</div>
            </div>

            <h3>Tax Burden by Income Level</h3>
            <div class="chart-container">
                <img src="data:image/svg+xml;base64,{tax_by_income_svg}" alt="Tax by Income Level">
                <div class="chart-caption">Figure 8: Average fuel tax percentage segmented by national income level</div>
            </div>

            <div class="callout info">
                <strong>Tax Policy Observation:</strong> High-income countries tend to have higher fuel tax percentages,
                with an average of {tax_by_income.get('High', 0):.1f}% compared to {tax_by_income.get('Low', 0):.1f}% for low-income countries.
                This reflects the use of fuel taxation as both a revenue mechanism and a policy tool for demand management.
            </div>
        </div>

        <!-- SECTION 5: INCOME SEGMENTATION -->
        <div class="section" id="income-segmentation">
            <h2>5. Fuel Affordability by Income Level</h2>

            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="kpi-value">{tax_by_income.get('High', 0):.1f}%</div>
                    <div class="kpi-label">High Income Tax %</div>
                </div>
                <div class="kpi-card warning">
                    <div class="kpi-value">{tax_by_income.get('Middle', 0):.1f}%</div>
                    <div class="kpi-label">Middle Income Tax %</div>
                </div>
                <div class="kpi-card success">
                    <div class="kpi-value">{tax_by_income.get('Low', 0):.1f}%</div>
                    <div class="kpi-label">Low Income Tax %</div>
                </div>
            </div>

            <h3>Analysis by Income Classification</h3>
            <table>
                <tr>
                    <th>Income Level</th>
                    <th>Avg Tax %</th>
                    <th>Avg Petrol Price</th>
                    <th>Subsidy Distribution</th>
                </tr>
                {''.join(f"<tr><td>{level}</td><td>{tax_by_income.get(level, 0):.1f}%</td><td>${df[df['income_level']==level]['petrol_usd_liter'].mean():.3f}</td><td>High: {len(df[(df['income_level']==level) & (df['subsidy_level']=='High')]['country'].unique())} / Low: {len(df[(df['income_level']==level) & (df['subsidy_level']=='Low')]['country'].unique())} countries</td></tr>" for level in ['High', 'Middle', 'Low'])}
            </table>

            <div class="highlight-box">
                <strong>Energy Equity Findings:</strong>
                <ul style="margin-top: 10px; margin-left: 20px;">
                    <li>Low-income countries have the lowest fuel tax burden, averaging {tax_by_income.get('Low', 0):.1f}%</li>
                    <li>High-income countries have higher fuel prices but also higher subsidy coverage</li>
                    <li>Middle-income countries show the most varied subsidy distribution</li>
                </ul>
            </div>
        </div>

        <!-- SECTION 6: KEY FINDINGS -->
        <div class="section" id="key-findings">
            <h2>6. Key Findings & Policy Implications</h2>

            <h3>Summary of Key Findings</h3>
            <ol class="findings-list">
                <li>
                    <strong>Strong Brent-Retail Linkage:</strong> The correlation coefficient of {brent_petrol_corr:.2f} between Brent Crude
                    and retail petrol prices confirms that international oil markets remain the primary price setter for global fuel costs.
                </li>
                <li>
                    <strong>Subsidies Significantly Buffer Price Shocks:</strong> High-subsidy countries show {subsidy_effect:.1f}% lower
                    retail prices compared to low-subsidy countries, demonstrating effective price dampening from government intervention.
                </li>
                <li>
                    <strong>Regional Price Inequality Persists:</strong> The regional spread between highest (Middle East) and lowest
                    (Africa) average prices reflects structural differences in subsidy and tax policies that persist over time.
                </li>
                <li>
                    <strong>Progressive Taxation in High-Income Countries:</strong> High-income countries collect {tax_by_income.get('High', 0):.0f}%
                    of fuel prices as tax compared to just {tax_by_income.get('Low', 0):.0f}% in low-income countries, enabling
                    high-income nations to use fiscal policy as a demand management tool.
                </li>
                <li>
                    <strong>COVID-19 and 2022 Crisis Revealed Vulnerability:</strong> Both the demand collapse of 2020 and the supply-driven
                    crisis of 2022 demonstrated how quickly global shocks transmit to retail markets, with limited buffering from
                    existing policy frameworks.
                </li>
            </ol>

            <h3>Policy Implications</h3>
            <div class="callout warning">
                <strong>For Subsidy Design:</strong> Policymakers should consider dynamic subsidy mechanisms that automatically
                adjust to crude price movements, rather than fixed subsidies that may become inadequate during extreme volatility.
            </div>
            <div class="callout info">
                <strong>For Tax Calibration:</strong> The data suggests tax levels in low-income countries may be too low to
                generate sufficient fiscal buffer during price spikes. Gradual tax increases could build resilience.
            </div>
            <div class="callout success">
                <strong>For Price Stabilization:</strong> Given the strong Brent-retail correlation, regional price stabilization
                mechanisms (like strategic reserves or coordinated release) could reduce consumer vulnerability to international shocks.
            </div>
        </div>

        <div class="footer">
            <p><strong>Methodology Note:</strong> All statistics are derived directly from the underlying dataset of weekly retail fuel prices
            across 84 countries. No values have been imputed or estimated beyond what is present in the source data.</p>
            <p style="margin-top: 10px;">Report: Global Fuel Price Trends & Policy Impact Analysis (2020–2026)</p>
        </div>
    </div>
</body>
</html>"""

